// SectionSearchIndex — local Quartz emitter plugin (multi-page variant).
//
// Wraps the stock `@quartz-community/content-index` emitter: sitemap.xml, RSS and
// the page-level `static/contentIndex.json` are generated by the stock code, then
// this plugin rewrites `contentIndex.json` so the index holds BOTH:
//
//   - one entry per PAGE (key = `slug`, the stock entry verbatim, including the
//     body text) so full-text search over note content keeps working;
//   - one entry per rendered heading (key = `slug#heading-id`, h1–h4) carrying
//     the heading's parent path + title, so a result can jump straight to a
//     section instead of only to the top of the note.
//
// Section entries are TITLE-ONLY (parent path + title in `content`): body text is
// indexed once, at page level, so a word-in-body query returns the note rather
// than every section of it.
//
// Heading ids are read from the rendered hast tree. `rehype-slug` assigns an id to
// every heading h1–h6, so section anchors resolve even below the TOC depth.
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { ContentIndex } from "@quartz-community/content-index";
const HEADING_TAG = /^h[1-6]$/;
// Index h1–h4 as sections. Deeper headings (h5/h6) stay merged into their parent
// section rather than becoming noise entries.
const SECTION_MAX_DEPTH = 4;
// cs-notes' table-of-contents transformer runs at its default maxDepth of 3, so a
// heading deeper than this has a rendered id but no TOC row. That is expected, not
// a defect, so only warn for ids that the TOC should have contained.
const TOC_MAX_DEPTH = 3;
function innerText(node) {
    if (node == null)
        return "";
    if (node.type === "text")
        return node.value ?? "";
    if (Array.isArray(node.children))
        return node.children.map(innerText).join("");
    return "";
}
function collectTocSlugs(entries, out) {
    for (const entry of entries ?? []) {
        if (entry.slug)
            out.add(entry.slug);
        collectTocSlugs(entry.children, out);
    }
    return out;
}
function splitPage(pageSlug, pageEntry, tree, tocSlugs) {
    const sections = [];
    // Heading hierarchy for the parent-path preview line (levels ascending).
    const stack = [];
    const visit = (node) => {
        if (node == null)
            return;
        if (node.type !== "element") {
            if (Array.isArray(node.children))
                node.children.forEach(visit);
            return;
        }
        const tagName = node.tagName ?? "";
        if (HEADING_TAG.test(tagName)) {
            const id = node.properties?.id;
            const title = innerText(node).replace(/\s+/g, " ").trim();
            const level = parseInt(tagName[1], 10);
            if (typeof id === "string" &&
                id.length > 0 &&
                title.length > 0 &&
                level <= SECTION_MAX_DEPTH) {
                if (level <= TOC_MAX_DEPTH && tocSlugs && !tocSlugs.has(id)) {
                    console.warn(`[SectionSearchIndex] heading id "${id}" on page "${pageSlug}" is missing from the TOC — search anchor may not match the TOC anchor.`);
                }
                while (stack.length > 0 && stack[stack.length - 1].level >= level)
                    stack.pop();
                const parentPath = stack.map((s) => s.title).join(" › ");
                stack.push({ level, title });
                sections.push({
                    key: `${pageSlug}#${id}`,
                    title,
                    links: pageEntry.links ?? [],
                    tags: pageEntry.tags ?? [],
                    content: parentPath ? `${parentPath} ${title}`.trim() : title,
                });
            }
            return;
        }
        if (Array.isArray(node.children))
            node.children.forEach(visit);
    };
    if (Array.isArray(tree?.children))
        tree.children.forEach(visit);
    return sections;
}
export default function SectionSearchIndex(opts) {
    const stock = ContentIndex(opts);
    async function rewrite(ctx, content) {
        const indexPath = join(ctx.argv.output, "static", "contentIndex.json");
        const raw = await readFile(indexPath, "utf-8");
        const pageIndex = JSON.parse(raw);
        const treesBySlug = new Map();
        const tocBySlug = new Map();
        for (const [tree, file] of content) {
            const slug = file?.data?.slug;
            if (typeof slug !== "string")
                continue;
            treesBySlug.set(slug, tree);
            tocBySlug.set(slug, collectTocSlugs(file?.data?.toc, new Set()));
        }
        const out = {};
        for (const [pageSlug, pageEntry] of Object.entries(pageIndex)) {
            // Page-level entry: keep the stock object verbatim so body search,
            // tag search and preview fetching behave exactly as before.
            out[pageSlug] = pageEntry;
            const tree = treesBySlug.get(pageSlug);
            if (!tree)
                continue;
            for (const section of splitPage(pageSlug, pageEntry, tree, tocBySlug.get(pageSlug) ?? new Set())) {
                out[section.key] = {
                    // The index KEY stays `pageSlug#anchor`: the search client builds its
                    // result href from the key (`slug: r` where r is the key) and ignores
                    // this field entirely. `slug` exists ONLY for the explorer, which
                    // calls `value.slug.split("/")` on every index value and throws
                    // (rendering no file tree at all) when one is missing. Parking it in
                    // the `tags/` namespace makes the stock explorer filter
                    // (`slugSegment !== "tags"`) discard the node, so it never shows up
                    // as a folder or a file.
                    slug: `tags/${section.key}`,
                    filePath: pageEntry.filePath ?? "",
                    title: section.title,
                    content: section.content,
                    links: section.links,
                    tags: section.tags,
                };
            }
        }
        for (const [key, value] of Object.entries(out)) {
            if (typeof value.slug !== "string") {
                throw new Error(`[SectionSearchIndex] entry "${key}" has no string slug — the explorer file trie will throw.`);
            }
        }
        await writeFile(indexPath, JSON.stringify(out));
    }
    return {
        name: "SectionSearchIndex",
        async emit(ctx, content, resources) {
            const outputs = await stock.emit(ctx, content, resources);
            await rewrite(ctx, content);
            return outputs;
        },
        async partialEmit(ctx, content, resources) {
            const outputs = stock.partialEmit
                ? await stock.partialEmit(ctx, content, resources)
                : await stock.emit(ctx, content, resources);
            await rewrite(ctx, content);
            return outputs;
        },
    };
}
